<style>
#ht-app [hidden]{display:none!important}
#ht-app{color:var(--text,#1f2937);--ht-error:#b42318}
.dark #ht-app{--ht-error:#fda29b}
.ht-picker .select2-selection__clear{display:none!important}
.ht-toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:14px 0}
.ht-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:12px}
.ht-card{background:var(--surface,#fff);color:var(--text,#1f2937);padding:18px;border:1px solid var(--border,#d1d5db);border-radius:14px;overflow-wrap:anywhere}
.ht-card h3{margin:0 0 8px;color:var(--text,#1f2937);font-weight:700}
.ht-card p{color:var(--text,#1f2937);line-height:1.7}
.ht-card small,.ht-muted{color:var(--text-muted,#6b7280)}
.ht-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
.ht-dialog{margin:auto;font-size:15px;background:var(--surface,#fff);color:var(--text,#1f2937);border:1px solid var(--border,#d1d5db);border-radius:16px;padding:22px;width:min(620px,94vw);max-height:90vh;overflow:auto}
.ht-dialog::backdrop{background:#0008}
.ht-field{display:block;margin:12px 0}
.ht-field input,.ht-field select,.ht-field textarea{width:100%;padding:10px;background:var(--surface,#fff);color:var(--text,#1f2937);border:1px solid var(--border,#d1d5db);border-radius:8px}
.ht-error{color:var(--ht-error,#b42318);white-space:pre-wrap}
.ht-body{white-space:pre-wrap}
.ht-photos img{max-width:100%;max-height:300px;margin:8px}
.ht-record{border-bottom:1px solid var(--border,#d1d5db);padding:14px 0}
#ht-dialog h2{font-size:20px}
.ht-pager{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:18px 0}
</style>
<div id="ht-app">
<h2>الموظفون وإجراءات الفريق</h2><p class="ht-muted">تظهر الإجراءات والسجلات المسموح بها لحسابك فقط. التحميلات المصورة لا تنشئ خصماً مالياً.</p>
<div class="ht-toolbar" id="ht-tabs"></div>
<div class="ht-toolbar"><div class="ht-picker" style="min-width:240px;max-width:100%;flex:1"><label for="ht-search">اسم الموظف أو الكود</label><select id="ht-search" data-placeholder="ابحث واختر موظفاً — جميع الموظفين" style="width:100%"><option value=""></option></select></div><button type="button" class="btn" id="ht-clear">إلغاء اختيار الموظف</button><select id="ht-status"><option value="">كل الحالات</option value="pending_manager">بانتظار المدير</option><option value="pending_hr">بانتظار الموارد البشرية</option><option value="issued">صادر</option><option value="approved">معتمد</option><option value="rejected">مرفوض</option><option value="cancelled">ملغى</option></select><label>من <input type="date" id="ht-from"></label><label>إلى <input type="date" id="ht-to"></label><button class="btn" id="ht-filter">بحث وتصفية</button><a class="btn" id="ht-export">تصدير Excel لجميع النتائج</a></div>
<p role="alert" id="ht-error" class="ht-error"></p><div id="ht-list" class="ht-grid"></div>
<div class="ht-pager"><button id="ht-prev" class="btn">السابق</button><span id="ht-count"></span><button id="ht-next" class="btn">التالي</button><label>عدد الصفوف <select id="ht-size"><option>10</option><option selected>25</option><option>50</option><option>100</option></select></label></div>
<dialog id="ht-dialog" class="ht-dialog" dir="rtl"><button class="btn" id="ht-close" style="float:left">إغلاق</button><div id="ht-detail"></div></dialog>
</div>
<script>
(()=>{
'use strict';
const base='/hr/team-data',csrf=<?= json_encode($csrf) ?>,$=id=>document.getElementById(id);
const kinds={employees:'الموظفون',notice:'التنبيهات',notice_request:'طلبات التنبيه',warning:'الإنذارات',transfer:'النقل',photo_loading:'التحميلات المصورة',all:'كل السجلات'};
const types={warnings:'الإنذارات السابقة',deductions:'الخصومات والتسويات',payroll:'كشوف الراتب',leaves:'الإجازات',attendance:'الحضور',advances:'السلف',evaluations:'التقييمات',tips:'التيبس',loadings:'التحميلات المالية'};
const labels={id:'الرقم',warning_type:'نوع الإنذار',reason:'السبب',warning_date:'التاريخ',status:'الحالة',adjustment_type:'نوع التسوية',amount:'المبلغ',period:'الشهر',base_salary:'الراتب الأساسي',total_earnings:'الاستحقاقات',total_deductions:'الاستقطاعات',net_salary:'الصافي',leave_type:'الإجازة',date_from:'من',date_to:'إلى',check_type:'البصمة',checked_at:'الوقت',advance_type:'السلفة',remaining_amount:'المتبقي',total_score:'الدرجة',evaluation_type:'نوع التقييم',notes:'ملاحظات'};
const valueLabel=v=>({created:'إنشاء الطلب',issued:'صادر',pending_manager:'بانتظار المدير',pending_hr:'بانتظار الموارد البشرية',approved:'معتمد',rejected:'مرفوض',cancelled:'ملغى',pending:'معلق',active:'نشط',resolved:'معالج',expired:'منتهي',paid:'مصروف',draft:'مسودة',verbal:'شفهي',written:'كتابي',final:'نهائي',deduction:'خصم',penalty:'جزاء',bonus:'مكافأة',raise:'زيادة',short:'قصيرة الأجل',long:'طويلة الأجل',monthly:'شهري',annual:'سنوية',unpaid:'بدون راتب',sick:'مرضية',emergency:'طارئة',in:'دخول',out:'خروج'}[v]??v);
let tab=({'/hr/notices':'notice','/hr/warnings':'warning','/hr/transfers':'transfer','/hr/photo-loadings':'photo_loading'})[location.pathname]||'employees',page=1,serial=0;
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function button(label,fn){const b=node('button',label,'btn');b.type='button';b.onclick=fn;return b;}
async function api(path,data){const r=await fetch(base+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data===undefined?undefined:JSON.stringify(data)});const b=await r.json();if(!r.ok||!b.ok)throw Error(b.error||'تعذر تحميل البيانات');return b.data;}
function query(){const q=new URLSearchParams({page:String(page),page_size:$('ht-size').value});if($('ht-search').value)q.set('employee_id',$('ht-search').value);if(tab!=='employees'){if(tab!=='all')q.set('kind',tab);for(const k of ['status','from','to'])if($('ht-'+k).value)q.set(k,$('ht-'+k).value);}return q;}
function dialog(){const d=$('ht-detail');d.replaceChildren();if(!$('ht-dialog').open)$('ht-dialog').showModal();return d;}
async function load(){const n=++serial;$('ht-error').textContent='';$('ht-list').textContent='جارٍ التحميل…';$('ht-export').hidden=tab==='employees';$('ht-search').hidden=false;$('ht-status').hidden=tab==='employees';for(const k of ['from','to'])$('ht-'+k).parentElement.hidden=tab==='employees';for(const [k,b]of Object.entries(tabButtons))b.disabled=k===tab;try{const q=query(),data=await api((tab==='employees'?'/employees':'/cases')+'?'+q);if(n!==serial)return;$('ht-list').replaceChildren();for(const row of data.rows){const card=node('article',undefined,'ht-card');card.append(node('h3',row.full_name));if(tab==='employees'){card.append(node('p',[row.emp_code,row.job_title,row.department].filter(Boolean).join(' • ')));const actions=node('div',undefined,'ht-actions');for(const [key,label]of Object.entries(row.actions))actions.append(button(label,()=>key==='archive'||key==='payslip'?archive(row,key==='payslip'?'payroll':'warnings',1):form(row,key)));card.append(actions);}else{card.append(node('p',row.kind_label+' • '+row.status_label),node('p',row.subject),node('small',row.created_at),button('عرض السجل',()=>detail(row.id)));}$('ht-list').append(card);}if(!data.rows.length)$('ht-list').append(node('p','لا توجد نتائج'));$('ht-count').textContent=`الصفحة ${page} — ${data.total} سجل`;$('ht-prev').disabled=page<=1;$('ht-next').disabled=page*data.page_size>=data.total;$('ht-export').href=base+'/export?'+q;}catch(e){if(n===serial){$('ht-list').replaceChildren();$('ht-error').textContent=e.message;}}}
const tabButtons={};for(const [k,label]of Object.entries(kinds)){tabButtons[k]=button(label,()=>{tab=k;page=1;$('ht-search').value='';loadOptions();load();});$('ht-tabs').append(tabButtons[k]);}
let optionSerial=0;
async function loadOptions(){
 const n=++optionSerial,select=$('ht-search');select.disabled=true;
 try{const q=new URLSearchParams({options:'1'});if(tab!=='employees'&&tab!=='all')q.set('kind',tab);
 const data=await api((tab==='employees'?'/employees':'/cases')+'?'+q);if(n!==optionSerial)return;
 select.replaceChildren(new Option('',''));for(const e of data.rows)select.add(new Option(`${e.full_name} (${e.emp_code})`,String(e.id)));
 if(window.reinitSelect2)window.reinitSelect2('#ht-search');
 }catch(e){if(n===optionSerial)$('ht-error').textContent=e.message;}finally{if(n===optionSerial)select.disabled=false;}
}
$('ht-search').onchange=()=>{page=1;load();};
$('ht-clear').onclick=()=>{$('ht-search').value='';if(window.reinitSelect2)window.reinitSelect2('#ht-search');page=1;load();};
$('ht-prev').onclick=()=>{page--;load();};$('ht-next').onclick=()=>{page++;load();};$('ht-filter').onclick=$('ht-size').onchange=()=>{page=1;load();};$('ht-close').onclick=()=>$('ht-dialog').close();
async function form(emp,action){const d=dialog();d.append(node('p','جارٍ التحميل…'));try{const schema=await api(`/employees/${emp.id}/form/${action}`);d.replaceChildren(node('h2',schema.title+' — '+emp.full_name));if(schema.advance_snapshot){const s=schema.advance_snapshot;d.append(node('p',`صافي الاستحقاق: ${s.net_entitlement??0} — المديونية: ${s.outstanding_debt??0} — الحد المتاح: ${s.remaining??0}`));}const f=node('form'),controls={},err=node('p','','ht-error');for(const field of schema.fields){const label=node('label',field.label,'ht-field');let input;if(field.type==='select'){input=node('select');input.append(new Option('اختر…',''));const opts=field.options||{};for(const [key,value]of Object.entries(opts)){if(typeof value==='object')input.append(new Option(value.label||value.value,value.value));else input.append(new Option(value,Array.isArray(opts)?value:key));}}else if(field.type==='textarea')input=node('textarea');else{input=node('input');input.type=field.type==='images'?'file':field.type||'text';if(input.type==='number')input.step='any';if(field.type==='images'){input.multiple=true;input.accept='image/jpeg,image/png,image/webp';}if(field.type==='month')input.value=new Date().toISOString().slice(0,7);}
input.required=!!field.required;controls[field.name]=input;label.append(input);f.append(label);}
const submit=node('button','إرسال','btn btn-success');submit.type='submit';f.append(err,submit);d.append(f);const key=crypto.randomUUID();f.onsubmit=async ev=>{ev.preventDefault();if(submit.disabled)return;submit.disabled=true;err.textContent='';try{const data={request_key:key};for(const [k,input]of Object.entries(controls)){if(input.type==='file'){if(input.files.length>5)throw Error('اختر حتى خمس صور');data[k]=await Promise.all([...input.files].map(file=>new Promise((resolve,reject)=>{if(file.size>5*1024*1024){reject(Error('الصورة أكبر من 5MB'));return;}const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);})));}else data[k]=input.value;}const result=await api(`/employees/${emp.id}/action/${action}`,data);d.replaceChildren(node('h2',result.message||'تم حفظ الطلب'));if(result.case_id)d.append(button('عرض السجل',()=>detail(result.case_id)));load();}catch(e){err.textContent=e.message;submit.disabled=false;}};}catch(e){d.replaceChildren(node('p',e.message,'ht-error'));}}
async function detail(id){const d=dialog();d.append(node('p','جارٍ التحميل…'));try{const r=await api('/cases/'+id);d.replaceChildren(node('h2',r.subject),node('p',r.full_name+' — '+(kinds[r.kind]||r.kind)),node('p',r.body,'ht-body'),node('p','حالة السجل: '+({'issued':'صادر','approved':'معتمد','pending_manager':'بانتظار المدير','pending_hr':'بانتظار الموارد البشرية','rejected':'مرفوض','cancelled':'ملغى'}[r.status]||r.status)),node('p','المنشئ: '+r.creator_name),node('p','القراءة: '+(r.employee_read_at||'لم يقرأ بعد')));if(r.new_manager_name)d.append(node('p','المدير الجديد: '+r.new_manager_name));const photos=node('div',undefined,'ht-photos');for(const f of r.files){const img=node('img');img.src=base+'/files/'+f.id;img.alt='صورة مرفقة';photos.append(img);}d.append(photos);for(const event of r.events)d.append(node('p',`${event.created_at} — ${event.actor_name}: ${valueLabel(event.action)} ${event.notes||''}`,'ht-muted'));if(r.actions.length){const notes=node('textarea');notes.placeholder='ملاحظات القرار؛ مطلوبة للرفض والإلغاء';d.append(notes);for(const action of r.actions)d.append(button({approve:'اعتماد / قبول',reject:'رفض',cancel:'إلغاء'}[action],async()=>{if(!confirm('تأكيد تسجيل هذا القرار؟'))return;try{await api('/cases/'+id+'/decide',{action,notes:notes.value});await detail(id);load();}catch(e){alert(e.message);}}));}await api('/cases/'+id+'/read',{});}catch(e){d.replaceChildren(node('p',e.message,'ht-error'));}}
async function archive(emp,type,p){const d=dialog();d.append(node('h2','أرشيف '+emp.full_name));const tabs=node('div',undefined,'ht-actions');for(const [k,label]of Object.entries(types)){if(['deductions','payroll','advances','tips','loadings'].includes(k)&&!emp.actions.payslip)continue;tabs.append(button(label,()=>archive(emp,k,1)));}tabs.append(button('التنبيهات والطلبات',async()=>{try{const x=await api('/cases?employee_id='+emp.id+'&page='+p+'&page_size=25');d.replaceChildren(node('h2','سجلات '+emp.full_name));for(const r of x.rows)d.append(button(r.subject+' — '+r.status_label,()=>detail(r.id)));const nav=node('div',undefined,'ht-pager');if(p>1)nav.append(button('السابق',()=>archiveCases(emp,p-1)));if(p*25<x.total)nav.append(button('التالي',()=>archiveCases(emp,p+1)));d.append(nav);}catch(e){d.append(node('p',e.message,'ht-error'));}}));d.append(tabs);try{const data=await api(`/employees/${emp.id}/archive?type=${type}&page=${p}&page_size=25`);d.append(node('h3',data.title+' — '+data.total+' سجل'));for(const row of data.rows){const c=node('div',undefined,'ht-record');for(const [k,v]of Object.entries(row))if(v!==null)c.append(node('p',(labels[k]||k)+': '+valueLabel(v)));if(type==='payroll')c.append(button('كشف الراتب التفصيلي',()=>payroll(emp,row.id)));d.append(c);}const nav=node('div',undefined,'ht-pager');if(p>1)nav.append(button('السابق',()=>archive(emp,type,p-1)));if(p*25<data.total)nav.append(button('التالي',()=>archive(emp,type,p+1)));d.append(nav);}catch(e){d.append(node('p',e.message,'ht-error'));}}
async function archiveCases(emp,p){await archive(emp,'warnings',p);const b=[...$('ht-detail').querySelectorAll('button')].find(b=>b.textContent==='التنبيهات والطلبات');b?.click();}
async function payroll(emp,pid){const d=dialog();try{const r=await api(`/employees/${emp.id}/payroll/${pid}`);d.append(node('h2','كشف الراتب — '+r.employee));for(const item of r.items)d.append(node('p',item.label+': '+item.value));d.append(button('طباعة',()=>{const frame=document.createElement('iframe');frame.style.display='none';document.body.append(frame);const doc=frame.contentDocument;doc.body.dir='rtl';doc.body.append(d.cloneNode(true));doc.querySelectorAll('button').forEach(b=>b.remove());frame.contentWindow.print();setTimeout(()=>frame.remove(),1000);}));}catch(e){d.append(node('p',e.message,'ht-error'));}}
const eid=new URLSearchParams(location.search).get('employee');if(eid&&/^\d+$/.test(eid))api('/employees/'+eid).then(e=>archiveCases(e,1)).catch(e=>$('ht-error').textContent=e.message);
loadOptions();load();const cid=new URLSearchParams(location.search).get('case');if(cid&&/^\d+$/.test(cid))detail(cid);
})();
</script>
